export type ProductAvailability = "in_stock" | "preorder" | "made_to_order";

export type Product = {
  slug: string;
  name: string;
  description: string;
  price: number;
  quantity: number; // entero ≥0; unidades disponibles, no qty de carrito
  compareAtPrice?: number;
  images: string[];
  category: string;
  tags: string[];
  inStock: boolean; // derivado: quantity > 0 (legacy JSON con solo inStock: fallback)
  availability?: ProductAvailability;
  featured: boolean;
};

/** Primer src usable. ⛔ `?? ""` — next/image con src vacío tumba prerender. */
export function firstImageSrc(images?: string[] | null): string | undefined {
  const raw = images?.[0];
  if (typeof raw !== "string") return undefined;
  const trimmed = raw.trim();
  return trimmed || undefined;
}

export function priceLabel(price: number, symbol: string): string {
  const hasCents = !Number.isInteger(price);
  const formatted = price.toLocaleString("es-AR", {
    minimumFractionDigits: hasCents ? 2 : 0,
    maximumFractionDigits: 2,
  });
  return `${symbol}${formatted}`;
}

/** Siempre el número, incluso 0. ⛔ copy de “hay stock”. */
export function quantityLabel(quantity: number): string {
  return `${quantity} disponibles`;
}

function asFiniteNumber(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function asString(value: unknown): string {
  return typeof value === "string" ? value : "";
}

function asStringArray(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.filter(
    (item): item is string => typeof item === "string" && item.trim() !== "",
  );
}

const AVAIL: ReadonlySet<string> = new Set([
  "in_stock",
  "preorder",
  "made_to_order",
]);

export function normalizeProduct(raw: unknown): Product | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const row = raw as Record<string, unknown>;
  const slug = asString(row.slug).trim();
  if (!slug) return null;
  const qtyRaw = row.quantity;
  const quantityIsInt =
    typeof qtyRaw === "number" && Number.isInteger(qtyRaw) && qtyRaw >= 0;
  const quantity = quantityIsInt ? qtyRaw : 0;
  const inStock = quantityIsInt ? quantity > 0 : Boolean(row.inStock);
  const availability =
    typeof row.availability === "string" && AVAIL.has(row.availability)
      ? (row.availability as ProductAvailability)
      : undefined;
  const compareAt = asFiniteNumber(row.compareAtPrice);
  return {
    slug,
    name: asString(row.name),
    description: asString(row.description),
    price: asFiniteNumber(row.price) ?? 0,
    quantity,
    ...(compareAt !== undefined ? { compareAtPrice: compareAt } : {}),
    images: asStringArray(row.images),
    category: asString(row.category),
    tags: asStringArray(row.tags),
    inStock,
    ...(availability ? { availability } : {}),
    featured: Boolean(row.featured),
  };
}

export function normalizeProducts(raw: unknown): Product[] {
  if (!Array.isArray(raw)) return [];
  const out: Product[] = [];
  for (const item of raw) {
    const product = normalizeProduct(item);
    if (product) out.push(product);
  }
  return out;
}

import { unstable_cache } from "next/cache";
import { draftMode } from "next/headers";
import { eq, sql } from "drizzle-orm";
import { getDb } from "@/db/client";
import { contentEntries } from "@/db/schema";
import { normalizeProducts, type Product } from "./types";
import productsJson from "../../../content/products/products.json";

export type { Product } from "./types";
export { firstImageSrc } from "./types";

async function getContentEntry(
  key: string,
  draft: boolean,
): Promise<unknown | null> {
  const db = getDb();
  if (!db) return null;
  if (draft) {
    const rows = await db
      .select({
        payload: sql<unknown>`COALESCE(${contentEntries.draftData}, ${contentEntries.data})`,
      })
      .from(contentEntries)
      .where(eq(contentEntries.contentKey, key))
      .limit(1);
    return rows[0]?.payload ?? null;
  }
  const rows = await db
    .select()
    .from(contentEntries)
    .where(eq(contentEntries.contentKey, key))
    .limit(1);
  return rows[0]?.data ?? null;
}

async function isDraftEnabled(): Promise<boolean> {
  try {
    const { isEnabled } = await draftMode();
    return isEnabled;
  } catch {
    return false;
  }
}

async function loadProducts(draft: boolean): Promise<Product[]> {
  if (!getDb()) return normalizeProducts(productsJson);
  const data = await getContentEntry("products/products", draft);
  if (!data || !Array.isArray(data)) return [];
  return normalizeProducts(data);
}

const getProductsCached = unstable_cache(
  async () => loadProducts(false),
  ["products/products"],
  { tags: ["content"] },
);

export async function getProducts(): Promise<Product[]> {
  if (await isDraftEnabled()) return loadProducts(true);
  return getProductsCached();
}

export async function getProduct(slug: string): Promise<Product | undefined> {
  const products = await getProducts();
  return products.find((p) => p.slug === slug);
}

export async function getFeaturedProducts(): Promise<Product[]> {
  const products = await getProducts();
  return products.filter((p) => p.featured);
}

export async function getCategories(): Promise<string[]> {
  const products = await getProducts();
  return Array.from(new Set(products.map((p) => p.category)));
}

import Link from "next/link";
import { firstImageSrc, priceLabel, quantityLabel, type Product } from "./types";

type ProductCardProps = {
  product: Product;
  currencySymbol: string;
};

export function ProductCard({ product, currencySymbol }: ProductCardProps) {
  const image = firstImageSrc(product.images);
  const compare =
    typeof product.compareAtPrice === "number" && product.price < product.compareAtPrice
      ? product.compareAtPrice
      : undefined;

  return (
    <article className="flex flex-col overflow-hidden rounded-2xl border border-border bg-card">
      <Link href={`/store/${product.slug}`} className="relative block aspect-square overflow-hidden bg-card">
        {image ? (
          <img
            src={image}
            alt={product.name}
            width={800}
            height={800}
            className="size-full object-cover"
          />
        ) : null}
      </Link>
      <div className="flex flex-1 flex-col p-4">
        {product.category ? (
          <p className="text-xs uppercase tracking-wide text-muted-foreground">{product.category}</p>
        ) : null}
        <Link href={`/store/${product.slug}`}>
          <h3 className="mt-1 font-heading text-lg font-medium leading-snug text-foreground">
            {product.name}
          </h3>
        </Link>
        <div className="mt-2 flex items-baseline gap-2">
          <span className="text-lg font-semibold text-primary">
            {priceLabel(product.price, currencySymbol)}
          </span>
          {compare ? (
            <span className="text-sm text-muted-foreground line-through">
              {priceLabel(compare, currencySymbol)}
            </span>
          ) : null}
        </div>
        <p className="mt-1 text-sm text-muted-foreground">
          {quantityLabel(product.quantity)}
        </p>
      </div>
    </article>
  );
}

import { ProductCard } from "./product-card";
import type { Product } from "./types";

type StoreCatalogProps = {
  products: Product[];
  currencySymbol: string;
};

export function StoreCatalog({ products, currencySymbol }: StoreCatalogProps) {
  if (products.length === 0) {
    return null;
  }

  return (
    <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
      {products.map((product) => (
        <ProductCard
          key={product.slug}
          product={product}
          currencySymbol={currencySymbol}
        />
      ))}
    </div>
  );
}

import type { ReactNode } from "react";
import Link from "next/link";
import { firstImageSrc, priceLabel, quantityLabel, type Product } from "./types";

type ProductDetailProps = {
  product: Product;
  currencySymbol: string;
  storeNav?: string;
  children?: ReactNode;
};

export function ProductDetail({
  product,
  currencySymbol,
  storeNav,
  children,
}: ProductDetailProps) {
  const cover = firstImageSrc(product.images);
  const gallery = (product.images ?? []).slice(1).filter(function (img): img is string {
    return typeof img === "string" && img.trim().length !== 0;
  });

  return (
    <section className="mx-auto max-w-7xl px-6 py-12 md:py-16">
      <nav className="flex items-center gap-1.5 text-sm text-muted-foreground">
        {storeNav ? (
          <Link href="/store" className="text-muted-foreground">
            {storeNav}
          </Link>
        ) : null}
        {product.category ? (
          <span className="text-foreground/70">{product.category}</span>
        ) : null}
      </nav>

      <div className="mt-8 grid gap-12 md:grid-cols-2">
        <div className="space-y-4">
          <div className="relative aspect-square overflow-hidden rounded-2xl bg-card">
            {cover ? (
              <img
                src={cover}
                alt={product.name}
                width={1200}
                height={1200}
                className="size-full object-cover"
              />
            ) : null}
          </div>
          {gallery.length > 0 ? (
            <div className="grid grid-cols-4 gap-3">
              {gallery.map((img, i) => (
                <div
                  key={`${img}-${i}`}
                  className="relative aspect-square overflow-hidden rounded-xl bg-card"
                >
                  <img
                    src={img}
                    alt={`${product.name} ${i + 2}`}
                    width={240}
                    height={240}
                    className="size-full object-cover"
                  />
                </div>
              ))}
            </div>
          ) : null}
        </div>

        <div className="flex flex-col justify-center">
          {product.category ? (
            <p className="text-sm uppercase tracking-wide text-muted-foreground">
              {product.category}
            </p>
          ) : null}
          <h1 className="mt-2 font-heading text-3xl font-semibold text-foreground md:text-4xl">
            {product.name}
          </h1>
          <p className="mt-5 text-3xl font-semibold text-primary">
            {priceLabel(product.price, currencySymbol)}
          </p>
          <p className="mt-2 text-sm text-muted-foreground">
            {quantityLabel(product.quantity)}
          </p>
          {product.description ? (
            <p className="mt-6 max-w-prose leading-relaxed text-muted-foreground">
              {product.description}
            </p>
          ) : null}
          {product.tags?.length ? (
            <div className="mt-5 flex flex-wrap gap-2">
              {product.tags.map((tag) => (
                <span
                  key={tag}
                  className="rounded-full border border-border bg-card px-3 py-1 text-xs font-medium text-foreground"
                >
                  {tag}
                </span>
              ))}
            </div>
          ) : null}
          {children}
        </div>
      </div>
    </section>
  );
}
